import { char, date, numeric, timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key generated by Postgres. */
export const pk = () => uuid("id").primaryKey().defaultRandom();

/** Decimal-safe money column. Values are strings in TS; use `@/lib/money` for arithmetic. */
export const money = (name: string) => numeric(name, { precision: 18, scale: 2 });

/** Rates, quantities, percentages (4 dp). */
export const decimal4 = (name: string) => numeric(name, { precision: 18, scale: 4 });

/** ISO-4217 currency code. Every monetary record stores its currency. */
export const currency = (name = "currency") => char(name, { length: 3 });

export const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });
export const day = (name: string) => date(name, { mode: "string" });

export const timestamps = {
  createdAt: ts("created_at").defaultNow().notNull(),
  updatedAt: ts("updated_at")
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date()),
};

/** Exchange rates (10 dp). */
export const fxRate = (name: string) => numeric(name, { precision: 20, scale: 10 });
